import os, re
from PIL import Image
import pytesseract
from datetime import datetime
import openpyxl

img_dir = '/app/workspace/dataset/img'
files = sorted([f for f in os.listdir(img_dir) if f.lower().endswith(('.png','.jpg','.jpeg','.tif','.tiff'))])

pat1 = re.compile(r'(\d{4})[\-/\.](\d{1,2})[\-/\.](\d{1,2})')
pat2 = re.compile(r'(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{2,4})')

priority_keywords = [
    'GRAND TOTAL',
    'TOTAL RM', 'TOTAL: RM',
    'TOTAL AMOUNT',
    'TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'
]
exclude_keywords = ['SUBTOTAL','SUB TOTAL','TAX','GST','SST','DISCOUNT','CHANGE','CASH TENDERED']

num_pat = re.compile(r'\b\d{1,3}(?:,\d{3})*(?:\.\d{2})\b|\b\d+\.\d{2}\b')

def extract_date(text):
    for m in pat1.finditer(text):
        y,mn,d = m.group(1), m.group(2), m.group(3)
        try:
            dt = datetime(int(y), int(mn), int(d))
            return dt.strftime('%Y-%m-%d')
        except Exception:
            continue
    for m in pat2.finditer(text):
        d,mn,y = m.group(1), m.group(2), m.group(3)
        if len(y)==2:
            y = '20'+y
        try:
            dt = datetime(int(y), int(mn), int(d))
            return dt.strftime('%Y-%m-%d')
        except Exception:
            continue
    return None


def extract_total(lines):
    up_lines = [ln.upper() for ln in lines]
    def find_num(ln):
        nums = num_pat.findall(ln)
        if nums:
            return nums[-1]
        return None
    for key in priority_keywords:
        for i,ln in enumerate(up_lines):
            if key in ln:
                if any(ex in ln for ex in exclude_keywords):
                    continue
                num = find_num(ln)
                if num:
                    return num
                if i+1 < len(up_lines):
                    num = find_num(up_lines[i+1])
                    if num:
                        return num
    for ln in reversed(up_lines):
        if any(ex in ln for ex in exclude_keywords):
            continue
        num = find_num(ln)
        if num:
            return num
    return None

rows=[]
for f in files:
    path = os.path.join(img_dir,f)
    img = Image.open(path)
    text = pytesseract.image_to_string(img)
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    date = extract_date(text)
    total = extract_total(lines)
    if total:
        total = total.replace(',','')
        try:
            total = f"{float(total):.2f}"
        except Exception:
            total = None
    rows.append((f, date, total))

# write excel
wb = openpyxl.Workbook()
ws = wb.active
ws.title = 'results'
ws.append(['filename','date','total_amount'])
for row in rows:
    ws.append(list(row))
output = '/app/workspace/stat_ocr.xlsx'
wb.save(output)
print('wrote', output)
PY
